import { useState } from 'react';
import {
  call,
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  RefName,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr02803Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [drawer, setDrawer] = useState<'all' | 'one' | ''>('');
  const [notificationId, setNotificationId] = useState<number | string>('');

  const readCount = results.filter((r) => r.kind === '개별').length;
  const totalChanged = results.reduce((sum, r) => sum + (typeof r.count === 'number' ? r.count : 0), 0);

  const addResult = (row: Row) => {
    setResults((prev) => [{ ...row, key: prev.length + 1 }, ...prev]);
  };

  const submitAll = async () => {
    const res = await call<Row>('POST', '/notifications/read-all', role, {});
    addResult({ kind: '전체', notificationId: '', count: res.updatedCount, readYn: true, readAt: '' });
    notify('모든 알림을 읽음 처리했습니다.');
    setDrawer('');
  };

  const submitOne = async () => {
    if (notificationId === '' || notificationId === null) {
      throw new Error('알림을 선택해 주세요.');
    }
    const res = await call<Row>('POST', '/notifications/' + notificationId + '/read', role, {});
    addResult({ kind: '개별', notificationId: res.notificationId, count: 1, readYn: res.readYn, readAt: res.readAt });
    notify('알림을 읽음 처리했습니다.');
    setNotificationId('');
    setDrawer('');
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>읽음 처리 현황</h2>
        <Tiles
          items={[
            ['처리 내역', <Num value={results.length} />],
            ['읽음 변경 알림', <Num value={totalChanged} />],
            ['개별 처리', <Num value={readCount} />],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>처리 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={() => setDrawer('all')}>모두 읽음 처리</button>
          <button type="button" onClick={() => setDrawer('one')}>개별 읽음 처리</button>
        </Band>
        <DataTable<Row>
          rows={results}
          empty="처리한 알림이 없습니다."
          columns={[
            { key: 'kind', label: '처리 구분' },
            {
              key: 'notificationId',
              label: '알림 ID',
              render: (r) => (r.notificationId === '' ? '전체' : <RefName table="notification" role={role} value={r.notificationId} />),
            },
            { key: 'count', label: '읽음으로 변경된 알림 수', render: (r) => <Num value={r.count} /> },
            { key: 'readYn', label: '읽음 여부', render: (r) => <Badge value={r.readYn ? '읽음' : '읽지 않음'} /> },
            { key: 'readAt', label: '읽음 일시', render: (r) => (r.readAt ? <DateText value={r.readAt} time /> : '-') },
          ]}
        />
      </section>
      {drawer === 'all' && (
        <Drawer title="모두 읽음 처리" onClose={() => setDrawer('')}>
          <Form onSubmit={submitAll} submit="모두 읽음 처리" note="본인의 읽지 않은 알림과 @멘션을 모두 읽음으로 바꿉니다." />
        </Drawer>
      )}
      {drawer === 'one' && (
        <Drawer title="개별 읽음 처리" onClose={() => setDrawer('')}>
          <Form onSubmit={submitOne} submit="읽음 처리">
            <Field label="알림 ID" required wide>
              <LookupSelect table="notification" role={role} value={notificationId} onChange={setNotificationId} placeholder="알림 선택" />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
